export const segmentsB: TranscriptSegment[] = [
  { segmentId: "sg-5dd7e1d0e1", sourceId: "sr-ebdaf47eb0", turnId: "tn-de3a95fac3", speakerId: "sp-631da7c3ae", sequenceIndex: 0, startTimeMs: 6000, endTimeMs: 11000, text: "To start, how long have you had your plot?" },
  { segmentId: "sg-17b19a1807", sourceId: "sr-ebdaf47eb0", turnId: "tn-2e8907911d", speakerId: "sp-cc8c8145dc", sequenceIndex: 1, startTimeMs: 11000, endTimeMs: 16074, text: "This is my first season, so about five months." },
  { segmentId: "sg-127e69d05d", sourceId: "sr-ebdaf47eb0", turnId: "tn-2e8907911d", speakerId: "sp-cc8c8145dc", sequenceIndex: 2, startTimeMs: 16074, endTimeMs: 22912, text: "I got the offer in February, which everyone told me was lucky." },
  { segmentId: "sg-5d31a6843e", sourceId: "sr-ebdaf47eb0", turnId: "tn-2e8907911d", speakerId: "sp-cc8c8145dc", sequenceIndex: 3, startTimeMs: 22912, endTimeMs: 28316, text: "I had been on the list for a bit under two years." },
  { segmentId: "sg-ed38081f03", sourceId: "sr-ebdaf47eb0", turnId: "tn-2e8907911d", speakerId: "sp-cc8c8145dc", sequenceIndex: 4, startTimeMs: 28316, endTimeMs: 41000, text: "My partner put us on it and then forgot, and the email came at a point where we had genuinely stopped expecting it." },
  { segmentId: "sg-ccd4018efd", sourceId: "sr-ebdaf47eb0", turnId: "tn-38a0510671", speakerId: "sp-631da7c3ae", sequenceIndex: 5, startTimeMs: 41000, endTimeMs: 46000, text: "What made you want one?" },
  { segmentId: "sg-bb5f39b9c3", sourceId: "sr-ebdaf47eb0", turnId: "tn-0ccb9a53ce", speakerId: "sp-cc8c8145dc", sequenceIndex: 6, startTimeMs: 46000, endTimeMs: 54547, text: "Partly food and mostly wanting a reason to be outside that was not exercise." },
  { segmentId: "sg-e22a9fcc5e", sourceId: "sr-ebdaf47eb0", turnId: "tn-0ccb9a53ce", speakerId: "sp-cc8c8145dc", sequenceIndex: 7, startTimeMs: 54547, endTimeMs: 64894, text: "I work from home and I was noticing that I could go three days without leaving the building." },
  { segmentId: "sg-0ca532c66c", sourceId: "sr-ebdaf47eb0", turnId: "tn-0ccb9a53ce", speakerId: "sp-cc8c8145dc", sequenceIndex: 8, startTimeMs: 64894, endTimeMs: 68380, text: "A gym membership did not stick." },
  { segmentId: "sg-f73950a18f", sourceId: "sr-ebdaf47eb0", turnId: "tn-0ccb9a53ce", speakerId: "sp-cc8c8145dc", sequenceIndex: 9, startTimeMs: 68380, endTimeMs: 83000, text: "I thought a plot might stick because things would die if I did not show up, which is a slightly grim motivation but it has worked." },
  { segmentId: "sg-cfd1f4a418", sourceId: "sr-ebdaf47eb0", turnId: "tn-3ca49716a1", speakerId: "sp-631da7c3ae", sequenceIndex: 10, startTimeMs: 83000, endTimeMs: 88000, text: "How has the first season gone?" },
  { segmentId: "sg-191045f224", sourceId: "sr-ebdaf47eb0", turnId: "tn-7fce89f5d5", speakerId: "sp-cc8c8145dc", sequenceIndex: 11, startTimeMs: 88000, endTimeMs: 95106, text: "Mixed, and better than I expected in the parts I did not plan." },
  { segmentId: "sg-c42226b80c", sourceId: "sr-ebdaf47eb0", turnId: "tn-7fce89f5d5", speakerId: "sp-cc8c8145dc", sequenceIndex: 12, startTimeMs: 95106, endTimeMs: 100034, text: "The growing has been about half successful." },
  { segmentId: "sg-2028603986", sourceId: "sr-ebdaf47eb0", turnId: "tn-7fce89f5d5", speakerId: "sp-cc8c8145dc", sequenceIndex: 13, startTimeMs: 100034, endTimeMs: 112870, text: "The tomatoes did well, the squash did too well, the carrots were a complete failure and I still do not know why." },
  { segmentId: "sg-1458c174de", sourceId: "sr-ebdaf47eb0", turnId: "tn-7fce89f5d5", speakerId: "sp-cc8c8145dc", sequenceIndex: 14, startTimeMs: 112870, endTimeMs: 122955, text: "I planted way too much in a space that turned out to be smaller than it looked in March." },
  { segmentId: "sg-ad04ade9e2", sourceId: "sr-ebdaf47eb0", turnId: "tn-7fce89f5d5", speakerId: "sp-cc8c8145dc", sequenceIndex: 15, startTimeMs: 122955, endTimeMs: 128112, text: "By July I could not walk between my own rows." },
  { segmentId: "sg-6bf68c9d8a", sourceId: "sr-ebdaf47eb0", turnId: "tn-7fce89f5d5", speakerId: "sp-cc8c8145dc", sequenceIndex: 16, startTimeMs: 128112, endTimeMs: 139000, text: "What has gone better than expected is that I like being there even when there is nothing to do." },
  { segmentId: "sg-689c181591", sourceId: "sr-ebdaf47eb0", turnId: "tn-83411bd514", speakerId: "sp-631da7c3ae", sequenceIndex: 17, startTimeMs: 139000, endTimeMs: 144000, text: "What was the hardest part?" },
  { segmentId: "sg-e6a3f991ef", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 18, startTimeMs: 144000, endTimeMs: 150658, text: "Water, without question, and not for the reason you would think." },
  { segmentId: "sg-af67e7ce05", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 19, startTimeMs: 150658, endTimeMs: 153363, text: "The physical part is fine." },
  { segmentId: "sg-5caeeb1e8c", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 20, startTimeMs: 153363, endTimeMs: 166991, text: "It is that there is a schedule, and I did not understand the schedule for about six weeks, and nobody told me I was doing it wrong." },
  { segmentId: "sg-8f04a75448", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 21, startTimeMs: 166991, endTimeMs: 176145, text: "I could tell something was off because people would go quiet when I was filling my cans." },
  { segmentId: "sg-7bd354b6ec", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 22, startTimeMs: 176145, endTimeMs: 190397, text: "Eventually a woman explained it to me at the gate, quite kindly, and it turned out I had been watering on the wrong days the entire time." },
  { segmentId: "sg-38aa5a9832", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 23, startTimeMs: 190397, endTimeMs: 192061, text: "I was mortified." },
  { segmentId: "sg-a023b2be80", sourceId: "sr-ebdaf47eb0", turnId: "tn-6dc22520d8", speakerId: "sp-cc8c8145dc", sequenceIndex: 24, startTimeMs: 192061, endTimeMs: 206001, text: "The information was on the corkboard, which I had never read, because I did not know the corkboard was where anything important lived." },
  { segmentId: "sg-6900a3ba4d", sourceId: "sr-ebdaf47eb0", turnId: "tn-3e015dd078", speakerId: "sp-631da7c3ae", sequenceIndex: 25, startTimeMs: 206000, endTimeMs: 212000, text: "Was that covered in the orientation?" },
  { segmentId: "sg-9983e9078d", sourceId: "sr-ebdaf47eb0", turnId: "tn-eaa012d9b3", speakerId: "sp-cc8c8145dc", sequenceIndex: 26, startTimeMs: 212000, endTimeMs: 213649, text: "It probably was." },
  { segmentId: "sg-100f2e6ca3", sourceId: "sr-ebdaf47eb0", turnId: "tn-eaa012d9b3", speakerId: "sp-cc8c8145dc", sequenceIndex: 27, startTimeMs: 213649, endTimeMs: 225298, text: "The orientation is one Saturday morning in March and it is about ninety minutes and it covers everything at once." },
  { segmentId: "sg-d42bdeadc5", sourceId: "sr-ebdaf47eb0", turnId: "tn-eaa012d9b3", speakerId: "sp-cc8c8145dc", sequenceIndex: 28, startTimeMs: 225298, endTimeMs: 238700, text: "Dues, the maintenance deadline, the workday requirement, the water schedule, the pesticide list, the gate code, the compost rules." },
  { segmentId: "sg-293c8aaf9d", sourceId: "sr-ebdaf47eb0", turnId: "tn-eaa012d9b3", speakerId: "sp-cc8c8145dc", sequenceIndex: 29, startTimeMs: 238700, endTimeMs: 250246, text: "I remember maybe a fifth of it, and I remember the parts that were about money because those felt consequential." },
  { segmentId: "sg-d711c8afa8", sourceId: "sr-ebdaf47eb0", turnId: "tn-eaa012d9b3", speakerId: "sp-cc8c8145dc", sequenceIndex: 30, startTimeMs: 250246, endTimeMs: 255194, text: "Nothing was written down that I could take home." },
  { segmentId: "sg-2589280114", sourceId: "sr-ebdaf47eb0", turnId: "tn-eaa012d9b3", speakerId: "sp-cc8c8145dc", sequenceIndex: 31, startTimeMs: 255194, endTimeMs: 261998, text: "There is a handbook, apparently, and I found out about it in July." },
  { segmentId: "sg-9ae7b20314", sourceId: "sr-ebdaf47eb0", turnId: "tn-341f97bbc6", speakerId: "sp-631da7c3ae", sequenceIndex: 32, startTimeMs: 262000, endTimeMs: 267000, text: "How did you find out about it?" },
  { segmentId: "sg-ef013ef008", sourceId: "sr-ebdaf47eb0", turnId: "tn-048aaf783b", speakerId: "sp-cc8c8145dc", sequenceIndex: 33, startTimeMs: 267000, endTimeMs: 276556, text: "Somebody mentioned it in passing, the way you would mention something obvious." },
  { segmentId: "sg-c206b9666c", sourceId: "sr-ebdaf47eb0", turnId: "tn-048aaf783b", speakerId: "sp-cc8c8145dc", sequenceIndex: 34, startTimeMs: 276556, endTimeMs: 289297, text: "I asked where it was and got a slightly confused answer, and then a link the next day from someone else." },
  { segmentId: "sg-4d072c0b65", sourceId: "sr-ebdaf47eb0", turnId: "tn-048aaf783b", speakerId: "sp-cc8c8145dc", sequenceIndex: 35, startTimeMs: 289297, endTimeMs: 291992, text: "It is a good handbook." },
  { segmentId: "sg-c54a8cf04a", sourceId: "sr-ebdaf47eb0", turnId: "tn-048aaf783b", speakerId: "sp-cc8c8145dc", sequenceIndex: 36, startTimeMs: 291992, endTimeMs: 300935, text: "It answers almost every question I spent the spring being confused about." },
  { segmentId: "sg-2b079eb99f", sourceId: "sr-ebdaf47eb0", turnId: "tn-048aaf783b", speakerId: "sp-cc8c8145dc", sequenceIndex: 37, startTimeMs: 300935, endTimeMs: 310001, text: "If I had read it in March I would have avoided the entire water situation." },
  { segmentId: "sg-f538d774cf", sourceId: "sr-ebdaf47eb0", turnId: "tn-853f646763", speakerId: "sp-631da7c3ae", sequenceIndex: 38, startTimeMs: 310000, endTimeMs: 316000, text: "Have you gotten to know other members?" },
  { segmentId: "sg-b969356101", sourceId: "sr-ebdaf47eb0", turnId: "tn-ddc4d48206", speakerId: "sp-cc8c8145dc", sequenceIndex: 39, startTimeMs: 316000, endTimeMs: 320811, text: "A few, and it took longer than I expected." },
  { segmentId: "sg-66aa4b96fd", sourceId: "sr-ebdaf47eb0", turnId: "tn-ddc4d48206", speakerId: "sp-cc8c8145dc", sequenceIndex: 40, startTimeMs: 320811, endTimeMs: 339369, text: "I go in the evenings after work, which is the busy time, so there are always people around, and for the first two months not one of them spoke to me beyond a nod." },
  { segmentId: "sg-d02e6d52a9", sourceId: "sr-ebdaf47eb0", turnId: "tn-ddc4d48206", speakerId: "sp-cc8c8145dc", sequenceIndex: 41, startTimeMs: 339369, endTimeMs: 343837, text: "I do not think that was unfriendliness." },
  { segmentId: "sg-fd9f2a1a57", sourceId: "sr-ebdaf47eb0", turnId: "tn-ddc4d48206", speakerId: "sp-cc8c8145dc", sequenceIndex: 42, startTimeMs: 343837, endTimeMs: 350940, text: "I think everyone assumed someone else had already welcomed me." },
  { segmentId: "sg-7eadfb3273", sourceId: "sr-ebdaf47eb0", turnId: "tn-ddc4d48206", speakerId: "sp-cc8c8145dc", sequenceIndex: 43, startTimeMs: 350940, endTimeMs: 364000, text: "The people I know now I met through the workday in April, which forced everyone into the same task for four hours." },
  { segmentId: "sg-63fc40d006", sourceId: "sr-ebdaf47eb0", turnId: "tn-992923b5b9", speakerId: "sp-631da7c3ae", sequenceIndex: 44, startTimeMs: 364000, endTimeMs: 369000, text: "What was the workday like?" },
  { segmentId: "sg-16fdf085d8", sourceId: "sr-ebdaf47eb0", turnId: "tn-964c1d9951", speakerId: "sp-cc8c8145dc", sequenceIndex: 45, startTimeMs: 369000, endTimeMs: 374537, text: "Genuinely fun, which I did not anticipate." },
  { segmentId: "sg-57a1a0d9f4", sourceId: "sr-ebdaf47eb0", turnId: "tn-964c1d9951", speakerId: "sp-cc8c8145dc", sequenceIndex: 46, startTimeMs: 374537, endTimeMs: 389831, text: "I was on a crew spreading wood chips on the paths with three other people, two of whom had been there over a decade." },
  { segmentId: "sg-1764a41c2e", sourceId: "sr-ebdaf47eb0", turnId: "tn-964c1d9951", speakerId: "sp-cc8c8145dc", sequenceIndex: 47, startTimeMs: 389831, endTimeMs: 397082, text: "You cannot spread wood chips for four hours in silence." },
  { segmentId: "sg-80799b8042", sourceId: "sr-ebdaf47eb0", turnId: "tn-964c1d9951", speakerId: "sp-cc8c8145dc", sequenceIndex: 48, startTimeMs: 397082, endTimeMs: 408288, text: "By the end I knew who they were and what they grew and which parts of the site flood." },
  { segmentId: "sg-5106763354", sourceId: "sr-ebdaf47eb0", turnId: "tn-964c1d9951", speakerId: "sp-cc8c8145dc", sequenceIndex: 49, startTimeMs: 408288, endTimeMs: 421999, text: "That was more useful than the orientation by a wide margin, and it was not designed to be useful at all." },
  { segmentId: "sg-b5736dba97", sourceId: "sr-ebdaf47eb0", turnId: "tn-dcc9bd3b7e", speakerId: "sp-631da7c3ae", sequenceIndex: 50, startTimeMs: 422000, endTimeMs: 427000, text: "Have you had any conflict?" },
  { segmentId: "sg-67498d9491", sourceId: "sr-ebdaf47eb0", turnId: "tn-fbd6e900e1", speakerId: "sp-cc8c8145dc", sequenceIndex: 51, startTimeMs: 427000, endTimeMs: 436123, text: "Not directly, and I have been aware of conflict happening near me." },
  { segmentId: "sg-14d1c6fb30", sourceId: "sr-ebdaf47eb0", turnId: "tn-fbd6e900e1", speakerId: "sp-cc8c8145dc", sequenceIndex: 52, startTimeMs: 436123, endTimeMs: 450222, text: "There is a disagreement about the two raised beds by the gate that seems to resurface every few weeks." },
  { segmentId: "sg-eba44b6591", sourceId: "sr-ebdaf47eb0", turnId: "tn-fbd6e900e1", speakerId: "sp-cc8c8145dc", sequenceIndex: 53, startTimeMs: 450222, endTimeMs: 471371, text: "I do not fully understand it and I have deliberately stayed out of it, because I have been there five months and I do not think I have earned an opinion." },
  { segmentId: "sg-994ffc1fb4", sourceId: "sr-ebdaf47eb0", turnId: "tn-fbd6e900e1", speakerId: "sp-cc8c8145dc", sequenceIndex: 54, startTimeMs: 471371, endTimeMs: 479250, text: "What I notice is that nobody explains the history to you." },
  { segmentId: "sg-6c36969a77", sourceId: "sr-ebdaf47eb0", turnId: "tn-fbd6e900e1", speakerId: "sp-cc8c8145dc", sequenceIndex: 55, startTimeMs: 479250, endTimeMs: 490999, text: "You catch about a third of a conversation and you can tell there are years behind it." },
  { segmentId: "sg-6597b2a6d4", sourceId: "sr-ebdaf47eb0", turnId: "tn-eb758edc10", speakerId: "sp-631da7c3ae", sequenceIndex: 56, startTimeMs: 491000, endTimeMs: 497000, text: "Does that make it harder to participate?" },
  { segmentId: "sg-1228172c18", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 57, startTimeMs: 497000, endTimeMs: 509436, text: "Yes, and I think that is the main thing separating me from the people who have been there a while." },
  { segmentId: "sg-d533c88905", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 58, startTimeMs: 509436, endTimeMs: 513243, text: "It is not gardening knowledge." },
  { segmentId: "sg-7b938cff09", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 59, startTimeMs: 513243, endTimeMs: 515654, text: "I can look that up." },
  { segmentId: "sg-d4fd0a5d72", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 60, startTimeMs: 515654, endTimeMs: 529232, text: "It is that every rule has a story attached, and the story is what tells you how seriously to take the rule." },
  { segmentId: "sg-59786232ea", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 61, startTimeMs: 529232, endTimeMs: 535196, text: "The maintenance deadline sounds harsh on paper." },
  { segmentId: "sg-985c14bbd9", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 62, startTimeMs: 535196, endTimeMs: 556134, text: "Then somebody tells you about a plot that sat abandoned all summer and grew a bindweed problem that took three years to clear, and the deadline stops sounding harsh." },
  { segmentId: "sg-1986aae330", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 63, startTimeMs: 556134, endTimeMs: 558926, text: "Nobody hands you that." },
  { segmentId: "sg-fd0a46bf94", sourceId: "sr-ebdaf47eb0", turnId: "tn-15e8ea1beb", speakerId: "sp-cc8c8145dc", sequenceIndex: 64, startTimeMs: 558926, endTimeMs: 564002, text: "You pick it up in fragments over a year." },
  { segmentId: "sg-11f51df262", sourceId: "sr-ebdaf47eb0", turnId: "tn-7dc3f73a3a", speakerId: "sp-631da7c3ae", sequenceIndex: 65, startTimeMs: 564000, endTimeMs: 569000, text: "Will you renew for next season?" },
  { segmentId: "sg-fd7f7424bd", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 66, startTimeMs: 569000, endTimeMs: 573251, text: "Yes, and I was not sure in June." },
  { segmentId: "sg-c11f6d93bd", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 67, startTimeMs: 573251, endTimeMs: 576306, text: "June was the low point." },
  { segmentId: "sg-367f21fe99", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 68, startTimeMs: 576306, endTimeMs: 592114, text: "Everything needed water, the squash was out of control, I had a work deadline, and I went eleven days without going in." },
  { segmentId: "sg-8b26b63f79", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 69, startTimeMs: 592114, endTimeMs: 609915, text: "When I came back it looked like a failure, and I sat on the bench by the compost for a while genuinely considering giving up the plot." },
  { segmentId: "sg-2502e98817", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 70, startTimeMs: 609915, endTimeMs: 629974, text: "What changed it was that a neighbor two plots down came over and said something like, this is the month everyone quits, do not quit in the worst month." },
  { segmentId: "sg-e54746b1df", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 71, startTimeMs: 629974, endTimeMs: 635022, text: "Then he helped me cut the squash back." },
  { segmentId: "sg-b43f9ca40d", sourceId: "sr-ebdaf47eb0", turnId: "tn-165296980e", speakerId: "sp-cc8c8145dc", sequenceIndex: 72, startTimeMs: 635022, endTimeMs: 641000, text: "Twenty minutes of his time and I am renewing." },
  { segmentId: "sg-4770d5e3a4", sourceId: "sr-ebdaf47eb0", turnId: "tn-580086352d", speakerId: "sp-631da7c3ae", sequenceIndex: 73, startTimeMs: 641000, endTimeMs: 648000, text: "What would you tell someone starting next spring?" },
  { segmentId: "sg-5ceb02e8ad", sourceId: "sr-ebdaf47eb0", turnId: "tn-b4630772fa", speakerId: "sp-cc8c8145dc", sequenceIndex: 74, startTimeMs: 648000, endTimeMs: 654486, text: "Read the handbook before you plant anything." },
  { segmentId: "sg-cbea79cdb2", sourceId: "sr-ebdaf47eb0", turnId: "tn-b4630772fa", speakerId: "sp-cc8c8145dc", sequenceIndex: 75, startTimeMs: 654486, endTimeMs: 659940, text: "Plant half of what you want to plant." },
  { segmentId: "sg-f4b8187db7", sourceId: "sr-ebdaf47eb0", turnId: "tn-b4630772fa", speakerId: "sp-cc8c8145dc", sequenceIndex: 76, startTimeMs: 659940, endTimeMs: 667457, text: "Go to the workday even if you have a reason not to." },
  { segmentId: "sg-9b4d61268a", sourceId: "sr-ebdaf47eb0", turnId: "tn-b4630772fa", speakerId: "sp-cc8c8145dc", sequenceIndex: 77, startTimeMs: 667457, endTimeMs: 683229, text: "And ask a question early, because the longer you wait the more embarrassing it gets to ask something basic." },
  { segmentId: "sg-8157203f72", sourceId: "sr-ebdaf47eb0", turnId: "tn-b4630772fa", speakerId: "sp-cc8c8145dc", sequenceIndex: 78, startTimeMs: 683229, endTimeMs: 699001, text: "I spent six weeks watering on the wrong days rather than asking a question I was afraid would sound stupid." },
  { segmentId: "sg-b0772c788a", sourceId: "sr-ebdaf47eb0", turnId: "tn-96262c657f", speakerId: "sp-631da7c3ae", sequenceIndex: 79, startTimeMs: 699000, endTimeMs: 705000, text: "Anything the garden could do differently?" },
  { segmentId: "sg-73ca70591c", sourceId: "sr-ebdaf47eb0", turnId: "tn-d59246bacb", speakerId: "sp-cc8c8145dc", sequenceIndex: 80, startTimeMs: 705000, endTimeMs: 709987, text: "Send the handbook with the offer email." },
  { segmentId: "sg-2c00f54a3b", sourceId: "sr-ebdaf47eb0", turnId: "tn-d59246bacb", speakerId: "sp-cc8c8145dc", sequenceIndex: 81, startTimeMs: 709987, endTimeMs: 715869, text: "That is the whole answer and it costs nothing." },
  { segmentId: "sg-b5919d130b", sourceId: "sr-ebdaf47eb0", turnId: "tn-d59246bacb", speakerId: "sp-cc8c8145dc", sequenceIndex: 82, startTimeMs: 715869, endTimeMs: 726354, text: "Everything I was confused about was written down somewhere I did not know existed." },
  { segmentId: "sg-6fd0b1ea87", sourceId: "sr-ebdaf47eb0", turnId: "tn-d59246bacb", speakerId: "sp-cc8c8145dc", sequenceIndex: 83, startTimeMs: 726354, endTimeMs: 744000, text: "There is a real gap between the information existing and the information reaching a person, and the garden treats those as the same thing." },
  { segmentId: "sg-478c69dcca", sourceId: "sr-ebdaf47eb0", turnId: "tn-c76383930b", speakerId: "sp-631da7c3ae", sequenceIndex: 84, startTimeMs: 744000, endTimeMs: 749000, text: "Thank you, this is very useful." },
  { segmentId: "sg-1d4ce408e2", sourceId: "sr-ebdaf47eb0", turnId: "tn-e5fbeec100", speakerId: "sp-cc8c8145dc", sequenceIndex: 85, startTimeMs: 749000, endTimeMs: 750787, text: "Happy to help." },
  { segmentId: "sg-6dec3f2baf", sourceId: "sr-ebdaf47eb0", turnId: "tn-e5fbeec100", speakerId: "sp-cc8c8145dc", sequenceIndex: 86, startTimeMs: 750787, endTimeMs: 761000, text: "Ask me again next year and I expect I will have completely different complaints." },
];
